## Theme Switcher

### Uso Básico

```typescript
// En tu componente
import { ThemeSwitcherComponent } from './shared/components/theme-switcher/theme-switcher.component';

@Component({
  standalone: true,
  imports: [ThemeSwitcherComponent],
  template: `<app-theme-switcher></app-theme-switcher>`
})
export class MyComponent {}
```

### Uso Avanzado con el Servicio

```typescript
import { Component, OnInit } from '@angular/core';
import { ThemeService, Theme } from './core/services/theme.service';

@Component({
  selector: 'app-settings',
  template: `
    <div class="settings">
      <h2>Configuración de Tema</h2>
      <p>Tema actual: {{ currentTheme }}</p>

      <button (click)="setLightTheme()">Tema Claro</button>
      <button (click)="setDarkTheme()">Tema Oscuro</button>
      <button (click)="toggleTheme()">Alternar</button>
    </div>
  `
})
export class SettingsComponent implements OnInit {
  currentTheme: Theme = 'light';

  constructor(private themeService: ThemeService) {}

  ngOnInit(): void {
    this.themeService.theme$.subscribe(theme => {
      this.currentTheme = theme;
      console.log('Tema cambiado a:', theme);
    });
  }

  setLightTheme(): void {
    this.themeService.setTheme('light');
  }

  setDarkTheme(): void {
    this.themeService.setTheme('dark');
  }

  toggleTheme(): void {
    this.themeService.toggleTheme();
  }
}
```

---

## Modal

### Ejemplo Básico

```typescript
import { Component } from '@angular/core';
import { ModalComponent } from './shared/components/modal/modal.component';

@Component({
  selector: 'app-example',
  imports: [ModalComponent],
  template: `
    <button (click)="openModal()">Abrir Modal</button>

    <app-modal 
      [isOpen]="isModalOpen"
      [title]="'Confirmación'"
      (closed)="onModalClosed()">
      <p>¿Estás seguro de que quieres continuar?</p>
      <div class="modal-actions">
        <button (click)="confirm()">Confirmar</button>
        <button (click)="closeModal()">Cancelar</button>
      </div>
    </app-modal>
  `
})
export class ExampleComponent {
  isModalOpen = false;

  openModal(): void {
    this.isModalOpen = true;
  }

  closeModal(): void {
    this.isModalOpen = false;
  }

  onModalClosed(): void {
    console.log('Modal cerrado');
  }

  confirm(): void {
    console.log('Confirmado');
    this.closeModal();
  }
}
```

### Modal de Login

```typescript
@Component({
  template: `
    <app-modal 
      [isOpen]="isLoginOpen"
      [title]="'Iniciar Sesión'"
      [closeOnOverlayClick]="false"
      (closed)="onLoginClosed()">

      <form (submit)="onSubmit($event)">
        <div class="form-group">
          <label>Email:</label>
          <input type="email" [(ngModel)]="email" required>
        </div>

        <div class="form-group">
          <label>Contraseña:</label>
          <input type="password" [(ngModel)]="password" required>
        </div>

        <button type="submit">Entrar</button>
      </form>
    </app-modal>
  `
})
export class LoginComponent {
  isLoginOpen = false;
  email = '';
  password = '';

  onSubmit(event: Event): void {
    event.preventDefault();
    console.log('Login:', this.email, this.password);
    // Lógica de autenticación
  }

  onLoginClosed(): void {
    this.email = '';
    this.password = '';
  }
}
```

