// ============================================
// HEADER COMPONENT - BEM
// ============================================

@import '../../../../styles/00-settings/variables';
@import '../../../../styles/01-tools/mixins';

.header {
  background-color: $color-primary-0;
  box-shadow: $shadow-md;
  position: sticky;
  top: 0;
  z-index: $z-sticky;
  transition: box-shadow $transition-base;

  &__container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 72px;
    gap: $spacing-6;
  }

  // ----------------
  // LOGO
  // ----------------
  &__logo {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    height: 44px;
  }

  &__logo-link {
    display: flex;
    align-items: center;
    gap: $spacing-3;
    text-decoration: none;
    transition: transform $transition-base;
    height: 100%;

    &:hover {
      transform: scale(1.05);
    }

    &:focus {
      outline: 2px solid $color-neutral-1000;
      outline-offset: 4px;
      border-radius: $radius-sm;
    }
  }

  &__logo-image {
    height: 40px;
    width: auto;

    @include respond-to('md') {
      height: 44px;
    }
  }

  &__logo-icon {
    font-size: 2rem;
    line-height: 1;
  }

  &__logo-text {
    font-family: $font-secondary;
    font-size: $font-lg;
    font-weight: $font-weight-bold;
    color: $color-neutral-1000;
    white-space: nowrap;

    @include respond-to('md') {
      font-size: $font-xl;
    }
  }

  // ----------------
  // NAVEGACIÓN
  // ----------------
  &__nav {
    // Móvil: menú oculto por defecto
    position: fixed;
    top: 72px; // Altura del header
    left: 0;
    right: 0;
    background-color: $color-primary-0;
    max-height: 0;
    overflow: hidden;
    transition: max-height $transition-base;
    box-shadow: $shadow-md;

    @include respond-to('lg') {
      // Desktop: navegación visible en línea
      position: static;
      max-height: none;
      overflow: visible;
      background-color: transparent;
      box-shadow: none;
      flex: 1;
    }

    // Estado abierto (móvil)
    &--open {
      max-height: 400px;
    }
  }

  &__nav-list {
    display: flex;
    flex-direction: column;
    list-style: none;
    padding: $spacing-4 0;

    @include respond-to('lg') {
      flex-direction: row;
      align-items: center;
      justify-content: center;
      gap: $spacing-2;
      padding: 0;
    }
  }

  &__nav-item {
    border-bottom: 1px solid rgba($color-neutral-1000, 0.1);

    @include respond-to('lg') {
      border-bottom: none;
    }

    &:last-child {
      border-bottom: none;
    }
  }

  &__nav-link {
    display: flex;
    align-items: center;
    padding: $spacing-4 $spacing-6;
    color: $color-neutral-1000;
    font-weight: $font-weight-medium;
    text-decoration: none;
    transition: all $transition-base;
    position: relative;
    white-space: nowrap;

    @include respond-to('lg') {
      padding: $spacing-3 $spacing-4;
      height: 44px;
      border-radius: $radius-md;
    }

    &:hover {
      background-color: rgba($color-neutral-1000, 0.1);
      padding-left: $spacing-8;

      @include respond-to('lg') {
        padding-left: $spacing-4;
        background-color: rgba($color-neutral-1000, 0.15);
      }
    }

    &:focus {
      outline: 2px solid $color-neutral-1000;
      outline-offset: -2px;
    }

    // Estado activo
    &--active {
      background-color: rgba($color-neutral-1000, 0.2);
      font-weight: $font-weight-bold;

      @include respond-to('lg') {
        background-color: rgba($color-neutral-1000, 0.25);

        &::after {
          content: '';
          position: absolute;
          bottom: 0;
          left: $spacing-4;
          right: $spacing-4;
          height: 3px;
          background-color: $color-primary-3;
          border-radius: $radius-full;
        }
      }
    }
  }

  // ----------------
  // UTILIDADES
  // ----------------
  &__utilities {
    display: flex;
    align-items: center;
    gap: $spacing-3;
  }

  &__utility-btn {
    @include flex-center;
    width: 44px;
    height: 44px;
    flex-shrink: 0;
    background-color: transparent;
    border: 2px solid rgba($color-neutral-1000, 0.3);
    border-radius: $radius-md;
    color: $color-neutral-1000;
    cursor: pointer;
    transition: all $transition-base;

    &:hover {
      background-color: rgba($color-neutral-1000, 0.1);
      border-color: $color-neutral-1000;
      transform: translateY(-2px);
    }

    &:focus {
      outline: 2px solid $color-neutral-1000;
      outline-offset: 2px;
    }

    &:active {
      transform: translateY(0);
    }
  }

  &__utility-icon {
    width: 24px;
    height: 24px;
  }

  // ----------------
  // MENÚ MÓVIL TOGGLE
  // ----------------
  &__menu-toggle {
    @include flex-center;
    flex-direction: column;
    gap: 5px;
    width: 44px;
    height: 44px;
    flex-shrink: 0;
    background-color: transparent;
    border: 2px solid rgba($color-neutral-1000, 0.3);
    border-radius: $radius-md;
    cursor: pointer;
    transition: all $transition-base;
    padding: $spacing-2;

    @include respond-to('lg') {
      display: none; // Oculto en desktop
    }

    &:hover {
      background-color: rgba($color-neutral-1000, 0.1);
      border-color: $color-neutral-1000;
    }

    &:focus {
      outline: 2px solid $color-neutral-1000;
      outline-offset: 2px;
    }

    &--active {
      .header__menu-toggle-bar {
        &:nth-child(1) {
          transform: rotate(45deg) translateY(10px);
        }

        &:nth-child(2) {
          opacity: 0;
        }

        &:nth-child(3) {
          transform: rotate(-45deg) translateY(-10px);
        }
      }
    }
  }

  &__menu-toggle-bar {
    width: 24px;
    height: 3px;
    background-color: $color-neutral-1000;
    border-radius: $radius-full;
    transition: all $transition-base;
  }
}

