  // ----------------
  &__content {
    flex: 1;
    min-width: 0; // Para que funcione text-overflow
  }

  &__title {
    font-size: $font-base;
    font-weight: $font-weight-bold;
    margin: 0 0 $spacing-1 0;
    line-height: $line-height-tight;
  }

  &__message {
    font-size: $font-sm;
    line-height: $line-height-relaxed;
    margin: 0;
  }

  // ----------------
  // BOTÓN CERRAR
  // ----------------
  &__close {
    flex-shrink: 0;
    width: 24px;
    height: 24px;
    padding: 0;
    background: transparent;
    border: none;
    cursor: pointer;
    border-radius: $radius-sm;
    transition: all $transition-base;
    display: flex;
    align-items: center;
    justify-content: center;
    align-self: flex-start;

    &:hover {
      background-color: rgba(0, 0, 0, 0.1);
    }

    &:focus {
      outline: 2px solid currentColor;
      outline-offset: 2px;
    }

    svg {
      width: 100%;
      height: 100%;
    }
  }

  // ----------------
  // VARIANTES POR TIPO
  // ----------------

  // Success - Verde
  &--success {
    background-color: rgba($color-success, 0.1);
    border-color: $color-success;
    color: var(--text-primary);

    .alert__icon,
    .alert__close {
      color: $color-success;
    }

    .alert__title {
      color: var(--text-primary);
    }
  }

  // Error - Rojo
  &--error {
    background-color: rgba($color-error, 0.1);
    border-color: $color-error;
    color: var(--text-primary);

    .alert__icon,
    .alert__close {
      color: $color-error;
    }

    .alert__title {
      color: var(--text-primary);
    }
  }

  // Warning - Naranja/Amarillo
  &--warning {
    background-color: rgba($color-warning, 0.2);
    border-color: darken($color-warning, 10%);
    color: var(--text-primary);

    .alert__icon,
    .alert__close {
