    border-color: $color-info;
    color: var(--text-primary);

    .alert__icon,
    .alert__close {
      color: $color-info;
    }

    .alert__title {
      color: var(--text-primary);
    }
  }
}

// ----------------
// TEMA OSCURO - Ajustes específicos
// ----------------
[data-theme="dark"] {
  .alert {
    &--success {
      background-color: rgba($color-success, 0.2);
      color: var(--text-primary);
    }

    &--error {
      background-color: rgba($color-error, 0.2);
      color: var(--text-primary);
    }

    &--warning {
      background-color: rgba($color-warning, 0.3);
      border-color: $color-warning;
      color: var(--text-primary);

      .alert__icon,
      .alert__close {
        color: $color-warning;
      }
    }

    &--info {
      background-color: rgba($color-info, 0.2);
      color: var(--text-primary);
    }
  }
}

