  flex-direction: column;
  background-color: $color-neutral-1000;
  border-radius: $radius-lg;
  box-shadow: $shadow-sm;
  overflow: hidden;
  transition: all $transition-base;

  // ----------------
  // IMAGEN
  // ----------------
  &__image-wrapper {
    position: relative;
    width: 100%;
    overflow: hidden;
    background-color: $color-neutral-900;
  }

  &__image {
    width: 100%;
    height: 200px;
    object-fit: cover;
    display: block;
    transition: transform $transition-slow;
  }

  // ----------------
  // CONTENIDO
  // ----------------
  &__content {
    padding: $spacing-6;
    display: flex;
    flex-direction: column;
    gap: $spacing-4;
    flex: 1;
  }

  &__title {
    font-size: $font-xl;
    font-weight: $font-weight-bold;
    color: $color-neutral-0;
    margin: 0;
    line-height: $line-height-tight;
  }

  &__description {
    font-size: $font-base;
    color: $color-neutral-400;
    line-height: $line-height-relaxed;
    margin: 0;
  }

  &__body {
    flex: 1;
  }

  &__actions {
    display: flex;
    gap: $spacing-3;
    flex-wrap: wrap;
    margin-top: $spacing-2;

    // Ocultar si está vacío
    &:empty {
      display: none;
    }
  }

  // ----------------
  // VARIANTES
  // ----------------

  // Card horizontal
  &--horizontal {
    flex-direction: row;

    @media (max-width: $breakpoint-md) {
      flex-direction: column;
    }

    .card__image-wrapper {
      width: 40%;
      min-height: 100%;

      @media (max-width: $breakpoint-md) {
        width: 100%;
        height: 200px;
      }
    }

    .card__image {
      height: 100%;
      min-height: 250px;

      @media (max-width: $breakpoint-md) {
        height: 200px;
        min-height: auto;
      }
    }

    .card__content {
      width: 60%;

      @media (max-width: $breakpoint-md) {
        width: 100%;
      }
    }
  }

  // ----------------
  // ESTADOS
  // ----------------

  // Hoverable
  &--hoverable {
    cursor: pointer;

    &:hover {
      box-shadow: $shadow-lg;
      transform: translateY(-4px);

      .card__image {
        transform: scale(1.05);
      }
    }

    &:active {
      transform: translateY(-2px);
    }
  }

  // Focus (para accesibilidad)
  &:focus-within {
    outline: 2px solid $color-info;
    outline-offset: 2px;
  }
}

// ----------------
// VARIANTES DE TAMAÑO (opcional)
// ----------------

.card--compact {
  .card__content {
    padding: $spacing-4;
  }

  .card__image {
    height: 150px;
  }

  .card__title {
    font-size: $font-lg;
  }
}

.card--large {
  .card__content {
    padding: $spacing-8;
  }

  .card__image {
    height: 300px;
  }

  .card__title {
    font-size: $font-2xl;
  }
}

