/**
 * Tabs Component Styles
 * Implementa estilos para tabs horizontal y vertical
 * Compatible con el sistema de temas
 */

@import '../../../../styles/00-settings/variables';
@import '../../../../styles/01-tools/mixins';

.tabs {
  display: flex;
  flex-direction: column;
  width: 100%;

  // Layout horizontal
  &--horizontal {
    .tabs__list {
      flex-direction: row;
      border-bottom: $border-thin solid var(--border-color);
    }

    .tabs__indicator {
      bottom: 0;
      height: $border-medium;
    }
  }

  // Layout vertical
  &--vertical {
    flex-direction: row;

    .tabs__list {
      flex-direction: column;
      border-right: $border-thin solid var(--border-color);
      min-width: 200px;
    }

    .tabs__indicator {
      left: 0;
      width: 3px;
    }

    .tabs__panels {
      flex: 1;
      padding-left: $spacing-6;
    }
  }

  &__list {
    display: flex;
    position: relative;
    gap: 0;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  &__tab {
    display: inline-flex;
    align-items: center;
    gap: $spacing-2;
    padding: $spacing-4 $spacing-5;
    background: transparent;
    border: none;
    color: var(--text-secondary);
    font-size: $font-base;
    font-weight: $font-weight-medium;
    cursor: pointer;
    transition: color $transition-fast, background-color $transition-fast;
    white-space: nowrap;

    &:hover:not(:disabled) {
      color: var(--text-primary);
      background-color: var(--bg-hover);
    }

    &:focus {
      outline: none;
    }

    &:focus-visible {
      outline: $border-medium solid var(--color-primary);
      outline-offset: -$spacing-1;
      background-color: var(--bg-hover);
    }

    &--active {
      color: var(--color-primary);

      &:hover:not(:disabled) {
        color: var(--color-primary);
      }
    }

    &--disabled {
      opacity: 0.5;
      cursor: not-allowed;

      &:hover {
        color: var(--text-secondary);
        background-color: transparent;
      }
    }
  }

  &__tab-icon {
    @include flex-center;
    width: 18px;
    height: 18px;

    svg {
      width: 100%;
      height: 100%;
    }
  }

  &__tab-label {
    line-height: 1;
  }

  &__tab-badge {
    @include flex-center;
    min-width: 18px;
    height: 18px;
    padding: 0 $spacing-2;
    background-color: var(--color-error);
    color: $color-neutral-1000;
    font-size: $font-xs;
    font-weight: $font-weight-semibold;
    border-radius: $radius-full;
  }

  &__indicator {
    position: absolute;
    background-color: var(--color-primary);
    transition: all $transition-base;
    pointer-events: none;
  }

  &__panels {
    margin-top: $spacing-4;
  }

  &__panel {
    display: none;

    &--active {
      display: block;
      animation: fadeIn $transition-base;
    }
  }

  &__panel-content {
    color: var(--text-primary);
    line-height: $line-height-relaxed;

    p {
      margin: 0;

      & + p {
        margin-top: $spacing-4;
      }
    }
  }
}

// Animación de fade in
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(-$spacing-2);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

// Responsive
@include respond-to('sm') {
  .tabs {
    &--vertical {
      flex-direction: column;

      .tabs__list {
        flex-direction: row;
        border-right: none;
        border-bottom: $border-thin solid var(--border-color);
        min-width: auto;
        overflow-x: auto;
      }

      .tabs__panels {
        padding-left: 0;
        padding-top: $spacing-4;
      }
    }

    &__tab {
      padding: $spacing-3 $spacing-4;
      font-size: $font-sm;
    }
  }
}

