@include respond-to('sm') {
  .tabs {
    &--vertical {
      flex-direction: column;

      .tabs__list {
        flex-direction: row;
        border-right: none;
        border-bottom: $border-thin solid var(--border-color);
        min-width: auto;
        overflow-x: auto;
      }

      .tabs__panels {
        padding-left: 0;
        padding-top: $spacing-4;
      }
    }

    &__tab {
      padding: $spacing-3 $spacing-4;
      font-size: $font-sm;
    }
  }
}

.theme-switcher {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  background: transparent;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-radius: 0.5rem;
  color: #fff;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 0.875rem;
  font-weight: 500;
  height: 44px;
  min-width: 44px;
  flex-shrink: 0;

  @media (min-width: 769px) {
    min-width: 180px;
  }

  &:hover {
    background: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.5);
  }

  &:focus-visible {
    outline: 2px solid #fff;
    outline-offset: 2px;
  }

  &:active {
    transform: scale(0.95);
  }

  &__icon {
    flex-shrink: 0;
    width: 20px;
    height: 20px;
    transition: transform 0.3s ease;

    &--sun {
      animation: rotate 20s linear infinite;
    }

    &--moon {
      animation: pulse 2s ease-in-out infinite;
    }

    &--auto {
      animation: none;
    }
  }

  &:hover &__icon {
    transform: scale(1.1);
  }

  &__label {
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;

    @media (max-width: 768px) {
      display: none;
    }
  }
}

// Animaciones
@keyframes rotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.7;
  }
}

// ============================================
// THEME SWITCHER COMPONENT
// ============================================

@import '../../../../styles/00-settings/variables';
@import '../../../../styles/01-tools/mixins';

.theme-switcher {
  @include flex-center;
  justify-content: center;
  gap: $spacing-2;
  padding: $spacing-3 $spacing-4;
  background: transparent;
  border: $border-medium solid rgba($color-neutral-1000, 0.3);
  border-radius: $radius-md;
  color: $color-neutral-1000;
  cursor: pointer;
  transition: all $transition-base;
  font-size: $font-sm;
  font-weight: $font-weight-medium;
  height: 44px;
  min-width: 44px;
  flex-shrink: 0;

  @include respond-to('md') {
    min-width: 180px;
  }

  &:hover {
    background: rgba($color-neutral-1000, 0.1);
    border-color: rgba($color-neutral-1000, 0.5);
    transform: translateY(-$spacing-1);
  }

  &:focus-visible {
    outline: $border-medium solid $color-neutral-1000;
    outline-offset: $spacing-1;
  }

  &:active {
    transform: scale(0.95);
  }

  &__icon {
    flex-shrink: 0;
    width: 20px;
    height: 20px;
    transition: transform $transition-base;

    &--sun {
      animation: rotate 20s linear infinite;
    }

    &--moon {
      animation: pulse 2s ease-in-out infinite;
    }

    &--auto {
      animation: none;
    }
  }

  &:hover &__icon {
    transform: scale(1.1);
  }

  &__label {
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;

    @media (max-width: $breakpoint-md) {
      display: none;
    }
  }
}

// Animaciones
@keyframes rotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.7;
  }
}

.toast-container {
  position: fixed;
  top: 1rem;
  right: 1rem;
  z-index: 10000;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  max-width: 400px;
  pointer-events: none;

  @media (max-width: 768px) {
    left: 1rem;
    right: 1rem;
    max-width: none;
  }
}

.toast {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 1rem;
  background: var(--bg-surface, #1a1a1a);
  border-radius: 0.75rem;
  box-shadow: var(--shadow-lg);
  border: 1px solid;
  min-width: 300px;
  pointer-events: auto;
  position: relative;
  overflow: hidden;
  animation: slideIn 0.3s ease-out;

  @media (max-width: 768px) {
    min-width: auto;
  }

  // Tipos de toast
  &--success {
    border-color: var(--color-success, #10b981);

    .toast__icon {
      background: rgba(16, 185, 129, 0.15);
      color: var(--color-success, #10b981);
    }
  }

  &--error {
    border-color: var(--color-error, #ef4444);

    .toast__icon {
      background: rgba(239, 68, 68, 0.15);
      color: var(--color-error, #ef4444);
    }
  }

  &--warning {
    border-color: var(--color-warning, #f59e0b);

    .toast__icon {
      background: rgba(245, 158, 11, 0.15);
      color: var(--color-warning, #f59e0b);
    }
  }

  &--info {
    border-color: var(--color-info, #3b82f6);

    .toast__icon {
      background: rgba(59, 130, 246, 0.15);
      color: var(--color-info, #3b82f6);
    }
  }

  &__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.5rem;
    flex-shrink: 0;
    font-weight: 700;
    font-size: 1.25rem;
  }

  &__icon-symbol {
    display: block;
  }

  &__content {
    flex: 1;
    min-width: 0;
  }

  &__title {
    font-weight: 600;
    font-size: 0.95rem;
    color: var(--text-primary, #fff);
    margin-bottom: 0.25rem;
  }

  &__message {
    font-size: 0.875rem;
    color: var(--text-secondary, #ccc);
    line-height: 1.4;
    word-wrap: break-word;
  }

  &__action {
    margin-top: 0.75rem;
    padding: 0.5rem 1rem;
    background: var(--color-primary, #4f46e5);
    color: white;
    border: none;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;

    &:hover {
      background: #4338ca;
      transform: translateY(-1px);
    }

    &:active {
      transform: translateY(0);
    }
  }

  &__close {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
    background: transparent;
    border: none;
    color: var(--text-secondary, #999);
    cursor: pointer;
    padding: 0.25rem;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 0.25rem;
    transition: all 0.2s ease;

    &:hover {
      background: var(--bg-hover, rgba(255, 255, 255, 0.1));
      color: var(--text-primary, #fff);
    }

    svg {
      width: 16px;
      height: 16px;
    }
  }

  &__progress {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: rgba(255, 255, 255, 0.1);
    overflow: hidden;
  }

  &__progress-bar {
    height: 100%;
    background: currentColor;
    width: 100%;
    transform-origin: left;
    animation: progressBar linear forwards;
  }
}

// Animaciones
@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(100%);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes progressBar {
  from {
    transform: scaleX(1);
  }
  to {
    transform: scaleX(0);
  }
}

// Animación de salida
.toast.ng-leave {
  animation: slideOut 0.3s ease-out forwards;
}

@keyframes slideOut {
  from {
    opacity: 1;
    transform: translateX(0);
  }
  to {
    opacity: 0;
    transform: translateX(100%);
  }
}

// ============================================
// TOAST CONTAINER COMPONENT
// ============================================

@import '../../../../styles/00-settings/variables';
@import '../../../../styles/01-tools/mixins';

.toast-container {
  position: fixed;
  top: $spacing-4;
  right: $spacing-4;
  z-index: $z-tooltip;
  display: flex;
  flex-direction: column;
  gap: $spacing-3;
  max-width: 400px;
  pointer-events: none;

  @include respond-to('md') {
    top: $spacing-6;
    right: $spacing-6;
  }

  @media (max-width: $breakpoint-md) {
    left: $spacing-4;
    right: $spacing-4;
    max-width: none;
  }
}

.toast {
  display: flex;
  align-items: flex-start;
  gap: $spacing-3;
  padding: $spacing-4;
  background: var(--bg-surface);
  border-radius: $radius-xl;
  box-shadow: $shadow-xl;
  border: $border-thin solid;
  min-width: 300px;
  pointer-events: auto;
  position: relative;
  overflow: hidden;
  animation: slideIn $transition-base;

  @media (max-width: $breakpoint-md) {
    min-width: auto;
  }

  // Tipos de toast
  &--success {
    border-color: var(--color-success);

    .toast__icon {
      background: rgba($color-success, 0.15);
      color: var(--color-success);
    }
  }

  &--error {
    border-color: var(--color-error);

    .toast__icon {
      background: rgba($color-error, 0.15);
      color: var(--color-error);
    }
  }

  &--warning {
    border-color: var(--color-warning);

    .toast__icon {
      background: rgba($color-warning, 0.15);
      color: var(--color-warning);
    }
  }

  &--info {
    border-color: var(--color-info);

    .toast__icon {
      background: rgba($color-info, 0.15);
      color: var(--color-info);
    }
  }

  &__icon {
    @include flex-center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: $radius-md;
    flex-shrink: 0;
    font-weight: $font-weight-bold;
    font-size: $font-md;
  }

  &__icon-symbol {
    display: block;
  }

  &__content {
    flex: 1;
    min-width: 0;
  }

  &__title {
    font-weight: $font-weight-semibold;
    font-size: $font-base;
    color: var(--text-primary);
    margin-bottom: $spacing-1;
  }

  &__message {
    font-size: $font-sm;
    color: var(--text-secondary);
    line-height: $line-height-normal;
    word-wrap: break-word;
  }

  &__action {
    margin-top: $spacing-3;
    padding: $spacing-2 $spacing-4;
    background: var(--color-primary);
    color: $color-neutral-1000;
    border: none;
    border-radius: $radius-md;
    font-size: $font-sm;
    font-weight: $font-weight-medium;
    cursor: pointer;
    transition: all $transition-fast;

    &:hover {
      opacity: 0.9;
      transform: translateY(-$spacing-1);
    }

    &:active {
      transform: translateY(0);
    }
  }

  &__close {
    position: absolute;
    top: $spacing-3;
    right: $spacing-3;
    background: transparent;
    border: none;
    color: var(--text-secondary);
    cursor: pointer;
    padding: $spacing-1;
    @include flex-center;
    border-radius: $radius-sm;
    transition: all $transition-fast;

    &:hover {
      background: var(--bg-hover);
      color: var(--text-primary);
    }

    svg {
      width: 16px;
      height: 16px;
    }
  }

  &__progress {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: rgba(255, 255, 255, 0.1);
    overflow: hidden;
  }

  &__progress-bar {
    height: 100%;
    background: currentColor;
    width: 100%;
    transform-origin: left;
    animation: progressBar linear forwards;
  }
}

// Animaciones
@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(100%);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes progressBar {
  from {
    transform: scaleX(1);
  }
  to {
    transform: scaleX(0);
  }
}

// Animación de salida
.toast.ng-leave {
  animation: slideOut 0.3s ease-out forwards;
}

@keyframes slideOut {
  from {
    opacity: 1;
    transform: translateX(0);
  }
  to {
    opacity: 0;
    transform: translateX(100%);
  }
}

// ============================================
// HOME COMPONENT - Página de inicio
// ============================================

@import '../../../styles/00-settings/variables';
@import '../../../styles/01-tools/mixins';

.home {
  background: var(--bg-body);
  min-height: 100%;
  transition: background-color $transition-base;
}

// ----------------
// HERO SECTION
// ----------------
.hero {
  text-align: center;
  padding: $spacing-16 $spacing-8;
  background: var(--color-primary);
  color: $color-neutral-1000;
  border-radius: $radius-2xl;
  margin: 0 $spacing-8 $spacing-8;
  box-shadow: $shadow-lg;
  transition: all $transition-base;

  @include respond-to('md') {
    padding: $spacing-20 $spacing-12;
    margin: 0 $spacing-12 $spacing-12;
  }

  &__content {
    max-width: 50rem; // 800px
    margin: 0 auto;
  }

  h1 {
    font-size: $font-2xl;
    font-family: $font-secondary;
    font-weight: $font-weight-bold;
    margin-bottom: $spacing-4;
    color: $color-neutral-1000;
    line-height: $line-height-tight;

    @include respond-to('md') {
      font-size: $font-3xl;
      margin-bottom: $spacing-6;
    }

    @include respond-to('lg') {
      font-size: $font-4xl;
    }
  }

  p {
    font-size: $font-md;
    line-height: $line-height-relaxed;
    margin-bottom: $spacing-8;
    color: $color-neutral-1000;
    opacity: 0.95;

    @include respond-to('md') {
      font-size: $font-lg;
    }
  }

  &__actions {
    @include flex-center;
    gap: $spacing-4;
    flex-wrap: wrap;
  }
}

// ----------------
// FEATURED SECTION
// ----------------
.featured {
  padding: 0 $spacing-8 $spacing-12;

  @include respond-to('md') {
    padding: 0 $spacing-12 $spacing-16;
  }

  h2 {
    font-size: $font-xl;
    font-family: $font-secondary;
    font-weight: $font-weight-bold;
    color: var(--text-primary);
    margin-bottom: $spacing-6;
    transition: color $transition-base;

    @include respond-to('md') {
      font-size: $font-2xl;
      margin-bottom: $spacing-8;
    }
  }

  &__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(15.625rem, 1fr)); // 250px
    gap: $spacing-6;

    @include respond-to('lg') {
      grid-template-columns: repeat(3, 1fr);
    }
  }
}

// ----------------
// CARDS
// ----------------
.card {
  background: var(--bg-surface);
  padding: $spacing-6;
  border-radius: $radius-lg;
  border: $border-thin solid var(--border-color);
  box-shadow: $shadow-sm;
  transition: all $transition-base;

  &:hover {
    transform: translateY(-$spacing-2);
    box-shadow: $shadow-lg;
    border-color: var(--color-primary);
  }

  h3 {
    font-size: $font-lg;
    font-family: $font-secondary;
    font-weight: $font-weight-bold;
    color: var(--text-primary);
    margin-bottom: $spacing-2;
    transition: color $transition-base;
  }

  p {
    font-size: $font-base;
    color: var(--text-secondary);
    margin-bottom: $spacing-5;
    line-height: $line-height-normal;
    transition: color $transition-base;
  }
}

// ----------------
// BUTTONS
// ----------------
.btn {
  @include button-base(var(--color-primary), $color-neutral-1000);
  font-size: $font-base;
  font-weight: $font-weight-semibold;
  border-radius: $radius-md;
  text-align: center;
  gap: $spacing-2;

  &--primary {
    background: $color-neutral-1000;
    color: var(--color-primary);
    padding: $spacing-4 $spacing-8;
    box-shadow: $shadow-md;

    &:hover {
      background: var(--bg-secondary);
      transform: translateY(-$spacing-1);
      box-shadow: $shadow-lg;
    }

    &:active {
      transform: translateY(0);
      box-shadow: $shadow-sm;
    }
  }

  &--sm {
    padding: $spacing-3 $spacing-5;
    font-size: $font-sm;
    background: var(--color-primary);
    color: $color-neutral-1000;

    &:hover {
      opacity: 0.9;
      transform: translateY(-$spacing-1);
    }

    &:active {
      transform: translateY(0);
    }
  }
}

